const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(new Cesium.OpenStreetMapImageryProvider({
    url: 'https://tile.openstreetmap.org/',
    maximumLevel: 18
  })),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false
}));

viewer.scene.globe.enableLighting = false;

const landmarks = [
  {
    name: 'Statue of Liberty',
    lon: -74.0445,
    lat: 40.6892,
    color: Cesium.Color.RED,
    labelColor: Cesium.Color.RED
  },
  {
    name: 'Eiffel Tower',
    lon: 2.2945,
    lat: 48.8584,
    color: Cesium.Color.DODGERBLUE,
    labelColor: Cesium.Color.DODGERBLUE
  },
  {
    name: 'Sydney Opera House',
    lon: 151.2153,
    lat: -33.8568,
    color: Cesium.Color.LIME,
    labelColor: Cesium.Color.LIME
  }
];

for (const lm of landmarks) {
  viewer.entities.add({
    name: lm.name,
    position: Cesium.Cartesian3.fromDegrees(lm.lon, lm.lat),
    point: {
      pixelSize: 14,
      color: lm.color,
      outlineColor: Cesium.Color.WHITE,
      outlineWidth: 2,
      disableDepthTestDistance: Number.POSITIVE_INFINITY
    },
    label: {
      text: lm.name,
      font: 'bold 14px sans-serif',
      fillColor: Cesium.Color.WHITE,
      outlineColor: Cesium.Color.BLACK,
      outlineWidth: 2,
      style: Cesium.LabelStyle.FILL_AND_OUTLINE,
      pixelOffset: new Cesium.Cartesian2(0, -24),
      disableDepthTestDistance: Number.POSITIVE_INFINITY,
      showBackground: true,
      backgroundColor: lm.color.withAlpha(0.6),
      backgroundPadding: new Cesium.Cartesian2(6, 4)
    }
  });
}

// Zoom to show all three entities; use a high-altitude fixed view
// since the three landmarks span the globe, a wide overview works best
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(50.0, 20.0, 18000000),
  orientation: {
    heading: Cesium.Math.toRadians(0),
    pitch: Cesium.Math.toRadians(-90),
    roll: 0
  }
});
